function useIsAdmin() {
  const { backend } = useApp();
  const [admin, setAdmin] = useState(false);
  useEffect(() => {
    if (backend.kind !== 'supabase') return;
    let alive = true;
    backend.client.rpc('is_admin').then(({ data, error }) => alive && setAdmin(!error && data === true)).catch(() => {});
